using System.Globalization;
using System.Reflection;
using System.Text.Json.Nodes;

namespace Eve.Services.Core;

/// <summary>
/// The New Eden Store catalog: the store offers and products, the public offers they are granted from, and the fast-checkout
/// PLEX packs. It is static data: <c>Data/new-eden-store.v1.json</c>, an embedded resource generated by
/// <c>tools/dev/gen-new-eden-store-catalog.py</c> from EVE.js's seed table (the owner-approved data source). Shown prices are the
/// listed prices; every purchase is granted at no charge (the owner's policy for offers purchasable with real money).
/// </summary>
/// <remarks>The <see cref="Root"/> object is shared: readers must not mutate it.</remarks>
public sealed class NewEdenStoreCatalog
{
    public const string Schema = "eve.rs.new-eden-store.v1";
    private const string ResourceName = "new-eden-store.v1.json";

    private static readonly Lazy<NewEdenStoreCatalog> Loaded = new(() => Parse(ReadResource()));

    private NewEdenStoreCatalog(JsonObject root) => Root = root;

    /// <summary>The loaded catalog, read once per process.</summary>
    public static NewEdenStoreCatalog Default => Loaded.Value;

    /// <summary>The store snapshot in the shape the store services read: <c>config</c>, <c>stores</c>, <c>publicOffers</c>, <c>fastCheckout</c>.</summary>
    public JsonObject Root { get; }

    public bool StoreEnabled => Config["enabled"]?.GetValue<bool>() ?? false;

    public bool FastCheckoutEnabled =>
        StoreEnabled && Config["fastCheckoutEnabled"]?.GetValue<bool>() == true && FastCheckoutOffers.Count > 0;

    /// <summary>The client's <c>fake_vgs_enabled</c>: the in-client store is served when the store is enabled and has offers (EVE.js storeState.js:517).</summary>
    public bool FakeVgsEnabled => StoreEnabled && Stores.Any(store => store.Value is JsonObject { } entry && entry["offers"] is JsonArray { Count: > 0 });

    public string FakeFastCheckoutResponse => Config["fakeFastCheckoutResponse"]?.GetValue<string>() ?? "OK";

    public bool ChinaFunnelEnabled => Config["fakeChinaFunnelEnabled"]?.GetValue<bool>() ?? false;

    public string FakeBuyPlexOfferUrl => Config["fakeBuyPlexOfferUrl"]?.GetValue<string>() ?? string.Empty;

    public bool UseShellExecuteToBuyPlexOffer => Config["useShellExecuteToBuyPlexOffer"]?.GetValue<bool>() ?? true;

    /// <summary>The client's <c>fake_fast_checkout_plex_offers</c>: <c>[[quantity, currency, price], ...]</c> (EVE.js storeState.js:270).</summary>
    public string FastCheckoutPlexOffers
    {
        get
        {
            var tuples = new JsonArray();
            foreach (var offer in FastCheckoutOffers.OfType<JsonObject>())
            {
                tuples.Add(new JsonArray(
                    JsonValue.Create(offer["quantity"]?.GetValue<long>() ?? 0),
                    JsonValue.Create(offer["currency"]?.GetValue<string>() ?? string.Empty),
                    JsonValue.Create(Math.Round(offer["price"]?.GetValue<double>() ?? 0, 2, MidpointRounding.AwayFromZero))));
            }
            return tuples.ToJsonString();
        }
    }

    /// <summary>The fast-checkout offer with this id (the id the client sends), or null.</summary>
    public JsonObject? FindFastCheckoutOffer(long offerId) =>
        FastCheckoutOffers.OfType<JsonObject>().FirstOrDefault(offer => offer["id"]?.GetValue<long>() == offerId);

    private JsonObject Config => (JsonObject)Root["config"]!;

    private JsonObject Stores => (JsonObject)Root["stores"]!;

    public JsonArray FastCheckoutOffers => (JsonArray)((JsonObject)Root["fastCheckout"]!)["offers"]!;

    private static string ReadResource()
    {
        using var stream = typeof(NewEdenStoreCatalog).Assembly.GetManifestResourceStream(ResourceName)
            ?? throw new InvalidDataException($"The embedded resource {ResourceName} is missing.");
        using var reader = new StreamReader(stream);
        return reader.ReadToEnd();
    }

    /// <summary>Parses and checks the catalog: its schema, and the sections every reader needs.</summary>
    public static NewEdenStoreCatalog Parse(string json)
    {
        var root = JsonNode.Parse(json) as JsonObject ?? throw new InvalidDataException("The store catalog is not a JSON object.");
        if (root["meta"]?["schema"]?.GetValue<string>() != Schema)
            throw new InvalidDataException($"The store catalog schema is not {Schema}.");
        foreach (var section in new[] { "config", "stores", "publicOffers", "fastCheckout" })
            _ = root[section] ?? throw new InvalidDataException($"The store catalog has no {section} section.");
        return new NewEdenStoreCatalog(root);
    }
}
